        sse_encode_String(field, serializer);
        sse_encode_String(value, serializer);
      case BridgeError_InvalidAmount(field: final field, reason: final reason):
        sse_encode_i_32(4, serializer);
        sse_encode_String(field, serializer);
        sse_encode_String(reason, serializer);
      case BridgeError_ZoneClaim(field: final field, reason: final reason):
        sse_encode_i_32(5, serializer);
        sse_encode_String(field, serializer);
        sse_encode_String(reason, serializer);
      case BridgeError_ZoneCoverage(field: final field, needed: final needed):
        sse_encode_i_32(6, serializer);
        sse_encode_String(field, serializer);
        sse_encode_String(needed, serializer);
      case BridgeError_OutOfRange(field: final field, value: final value):
        sse_encode_i_32(7, serializer);
        sse_encode_String(field, serializer);
        sse_encode_String(value, serializer);
      case BridgeError_Unrepresentable(field: final field):
